CREATE TABLE "public"."store_settings" (
  "id"                                       integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "gcash_qr_url"                             text    DEFAULT ''::text,
  "location_id"                              uuid,
  "cashier_auto_approved_discount_limit_pct" numeric NOT NULL DEFAULT 10,
  CONSTRAINT "store_settings_cashier_discount_limit_check"
    CHECK (((cashier_auto_approved_discount_limit_pct >= (0)::numeric) AND (cashier_auto_approved_discount_limit_pct <= (100)::numeric))),
  CONSTRAINT "store_settings_location_id_fkey" FOREIGN KEY (location_id) REFERENCES public.locations(id) ON DELETE CASCADE,
  CONSTRAINT "store_settings_location_id_key" UNIQUE (location_id),
  CONSTRAINT "store_settings_pkey" PRIMARY KEY (id)
);

REVOKE ALL ON SEQUENCE "public"."store_settings_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."store_settings_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."store_settings_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."store_settings_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."store_settings_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."store_settings_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."store_settings_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."store_settings_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."store_settings" TO "service_role";

REVOKE ALL ON TABLE "public"."store_settings" FROM "anon";

GRANT MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE ON TABLE "public"."store_settings" TO "anon";

REVOKE ALL ON TABLE "public"."store_settings" FROM "authenticated";

GRANT MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE ON TABLE "public"."store_settings" TO "authenticated";

REVOKE ALL ON TABLE "public"."store_settings" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."store_settings" TO "postgres";
